String xepLoai(int score) {
  if (score >= 90) {
    return 'A';
  } else if (score >= 80) {
    return 'B';
  } else if (score >= 70) {
    return 'C';
  } else if (score >= 60) {
    return 'D';
  } else {
    return 'F';
  }
}

void main() {
  print('95 điểm: ${xepLoai(95)}');
  print('73 điểm: ${xepLoai(73)}');
  print('55 điểm: ${xepLoai(55)}');
}

int tongTuDen(int start, int end) {
  int sum = 0;
  for (int i = start; i <= end; i++) {
    sum += i;
  }
  return sum;
}

void main() {
  print('Tổng từ 1 đến 5: ${tongTuDen(1, 5)}');
  print('Tổng từ 10 đến 12: ${tongTuDen(10, 12)}');
}

List<int> demNguoc(int n) {
  final result = <int>[];
  int current = n;
  while (current >= 0) {
    result.add(current);
    current--;
  }
  return result;
}

void main() {
  print('Đếm ngược từ 5: ${demNguoc(5)}');
  print('Đếm ngược từ 3: ${demNguoc(3)}');
}

