    expect(calculate(10, 5, '/'), equals(2));
    expect(calculate(10, 4, '/'), closeTo(2.5, 0.01));
  });

  test('Invalid operator throws', () {
    expect(() => calculate(1, 2, '^'), throwsException);
    expect(() => calculate(1, 2, '%'), throwsException);
  });
}

exercises.solutionCode:
double calculate(double a, double b, String operator) {
  switch (operator) {
    case '+':
      return a + b;
    case '-':
      return a - b;
    case '*':
      return a * b;
    case '/':
      return a / b;
    default:
      throw Exception('Invalid operator: $operator');
  }
}

void main() {
  print(calculate(10, 5, '+'));
  print(calculate(10, 5, '-'));
  print(calculate(10, 5, '*'));
  print(calculate(10, 5, '/'));
}

